// The Biome Inspector's model: a world of one biome choice, generated by the GAME's own world code, its spawn chosen
// the way a new world chooses it, and a checklist of what that spawn should have.
//
// DOM-free, so the checklist runs in Node tests as well as on biome-inspector.html. What it covers is what a biome
// choice changes at the start of a world:
//   * a Nether choice starts beside a lit portal that leads to a random Overworld biome (dimensionSpawns.js);
//   * an End choice starts on its own kind of island -- only "The End" on the main island -- with a small End portal
//     home; End City beside an End city; and killing the dragon opens small gateways to an End city and back;
//   * Sunflower Plains grows sunflowers two blocks tall;
//   * an Overworld choice is that biome at the spawn.
import * as THREE from 'three';
import { BIOME_CATEGORIES, getBiomeDef } from './biomes.js';
import { BLOCKS, BLOCK_DEFS } from './blocks.js';
import { createAuditWorld } from './structureAudit.js';
import { placePlayerOnSurface } from './worldSpawn.js';
import { regenerateEndPlatform, PLATFORM } from './worldgen/generators/endFeatures.js';
import { placeEndWorldSpawn, placeNetherSpawnPortal, spawnPortalLink, openEndCityLinks, END_SPAWNS } from './dimensionSpawns.js';
import { endColumn, END_OUTER_RADIUS } from './endTerrain.js';
import { endStateFor } from './endProgression.js';

/** The picker: every biome choice of the new-world screen, by its category. */
export function inspectorBiomes() {
  return BIOME_CATEGORIES.map((cat) => ({
    id: cat.id, name: cat.name, icon: cat.icon,
    biomes: cat.biomes.filter((id) => getBiomeDef(id)?.id === id).map((id) => ({ id, name: getBiomeDef(id).name }))
  }));
}

/**
 * Generate a world of one biome choice and start a player in it, as a new world would.
 * @returns {Promise<object>} `{ biome, def, seed, world, game, spawn, centre, range }`
 */
export async function buildBiomeWorld({ biome = 'plains', seed = 4242, radiusChunks = 2 } = {}) {
  const { world, recorder } = await createAuditWorld({ seed, biome, difficulty: 'normal' });
  // Every structure the game places (createAuditWorld narrows them to one): villages, End cities.
  world.rebuildStructures?.();
  const player = { position: new THREE.Vector3(0, 0, 0), velocity: new THREE.Vector3(), spawnPosition: new THREE.Vector3(), yaw: 0, onGround: false };
  const game = { world, player };
  world.spawnPortals = null;
  let spawn;
  if (world.dimension === 'the_end') {
    const arrival = regenerateEndPlatform(world, BLOCKS);
    player.position.set(arrival.x, arrival.y, arrival.z);
    spawn = placeEndWorldSpawn(game, arrival);
  } else {
    spawn = placePlayerOnSurface(game);
    if (world.dimension === 'nether' && spawn?.found) placeNetherSpawnPortal(game, spawn);
  }
  const centre = { x: Math.floor(player.position.x), y: Math.floor(player.position.y), z: Math.floor(player.position.z) };
  const range = {
    minCx: Math.floor(centre.x / 16) - radiusChunks, maxCx: Math.floor(centre.x / 16) + radiusChunks,
    minCz: Math.floor(centre.z / 16) - radiusChunks, maxCz: Math.floor(centre.z / 16) + radiusChunks
  };
  for (let cx = range.minCx - 1; cx <= range.maxCx + 1; cx++) for (let cz = range.minCz - 1; cz <= range.maxCz + 1; cz++) world.getOrCreateChunk(cx, cz);
  return { biome, def: getBiomeDef(biome), seed: String(seed), world, recorder, game, spawn, centre, range };
}

/** Every block of the given ids within `r` blocks of the spawn (and 8 below to 24 above it). */
export function blocksNearSpawn(built, ids, r = 10, { below = 8, above = 24 } = {}) {
  const want = new Set(ids);
  const { world, centre } = built;
  const out = [];
  for (let x = -r; x <= r; x++) for (let z = -r; z <= r; z++) for (let y = -below; y <= above; y++) {
    const id = world.getVoxel(centre.x + x, centre.y + y, centre.z + z);
    if (want.has(id)) out.push({ x: centre.x + x, y: centre.y + y, z: centre.z + z, id });
  }
  return out;
}

/** Sunflowers in the generated area, and how many stand on their stalks. */
export function sunflowerCounts(built) {
  const { world, range } = built;
  let heads = 0, onStalks = 0;
  for (let cx = range.minCx; cx <= range.maxCx; cx++) for (let cz = range.minCz; cz <= range.maxCz; cz++) {
    for (let x = cx * 16; x < cx * 16 + 16; x++) for (let z = cz * 16; z < cz * 16 + 16; z++) for (let y = 1; y < 63; y++) {
      if (world.getVoxel(x, y, z) !== BLOCKS.SUNFLOWER) continue;
      heads++;
      if (world.getVoxel(x, y - 1, z) === BLOCKS.SUNFLOWER_STALK) onStalks++;
    }
  }
  return { heads, onStalks };
}

const ok = (label, pass, detail) => ({ label, ok: !!pass, detail });

/** The checklist for a built biome world: what this biome choice's start should have, and whether it does. */
export function biomeChecks(built) {
  const { world, spawn, centre, biome, def } = built;
  const checks = [];
  const feet = world.getVoxel(centre.x, centre.y, centre.z), head = world.getVoxel(centre.x, centre.y + 1, centre.z);
  const ground = world.getVoxel(centre.x, centre.y - 1, centre.z);
  const open = (id) => id === BLOCKS.AIR || BLOCK_DEFS[id]?.solid === false;
  checks.push(ok('The spawn has ground under it and room to stand', open(feet) && open(head) && !open(ground), `${BLOCK_DEFS[ground]?.name ?? ground} under the feet; ${spawn?.reason ?? ''}`));

  if (world.dimension === 'nether') {
    const portal = blocksNearSpawn(built, [BLOCKS.NETHER_PORTAL], 6, { below: 3, above: 6 });
    checks.push(ok('A lit Nether portal stands beside the spawn', portal.length >= 6, `${portal.length} portal blocks within 6 blocks`));
    const link = world.spawnPortals ? spawnPortalLink(world, 'nether', world.spawnPortals.nether) : null;
    const found = link ? world.mixedOverworldBiome(link.x, link.z) : null;
    checks.push(ok('It leads to a random Overworld biome', link && found === link.biome, link ? `${getBiomeDef(link.biome)?.name} at ${link.x}, ${link.z} (the Overworld there is ${getBiomeDef(found)?.name})` : 'no link'));
    const back = link ? spawnPortalLink(world, 'overworld', { x: link.x, z: link.z }) : null;
    checks.push(ok('A portal there leads back to this spawn', back && Math.hypot(back.x - world.spawnPortals.nether.x, back.z - world.spawnPortals.nether.z) < 2, back ? `back to ${back.x}, ${back.y}, ${back.z}` : 'no way back'));
  }

  if (world.dimension === 'the_end') {
    const kind = END_SPAWNS[biome] ?? 'main';
    const portal = blocksNearSpawn(built, [BLOCKS.END_PORTAL], 8);
    checks.push(ok('A small End portal home stands beside the spawn', portal.length >= 1, portal.length ? `at ${portal[0].x}, ${portal[0].y}, ${portal[0].z}; it leads to the Overworld` : 'none within 8 blocks'));
    const column = endColumn(world, centre.x, centre.z);
    const distance = Math.round(Math.hypot(centre.x, centre.z));
    if (kind === 'main') checks.push(ok('The End starts on the main island\'s obsidian platform', Math.hypot(centre.x - PLATFORM.x, centre.z - PLATFORM.z) < 3, `${distance} blocks from the middle`));
    else checks.push(ok('It does not start on the main island', distance >= END_OUTER_RADIUS, `${distance} blocks from the middle (the outer islands begin at ${END_OUTER_RADIUS})`));
    if (kind === 'small') checks.push(ok('On a small End island', column.island === 'small', `this island is ${column.island ?? 'none'}`));
    if (kind === 'big') checks.push(ok('On a big End island', column.island === 'big', `this island is ${column.island ?? 'none'} (${getBiomeDef(column.biome)?.name})`));
    if (kind === 'chorus') {
      const chorus = blocksNearSpawn(built, [BLOCKS.CHORUS_PLANT, BLOCKS.CHORUS_FLOWER], 16);
      checks.push(ok('Among chorus plants', chorus.length >= 10, `${chorus.length} chorus blocks within 16 blocks`));
    }
    if (kind === 'city') {
      const purpur = blocksNearSpawn(built, [BLOCKS.PURPUR_BLOCK, BLOCKS.PURPUR_PILLAR, BLOCKS.PURPUR_STAIRS].filter((id) => id !== undefined), 40, { below: 10, above: 40 });
      checks.push(ok('Beside an End city', purpur.length >= 50, `${purpur.length} purpur blocks within 40 blocks`));
    }
  }

  if (biome === 'sunflower_plains') {
    const { heads, onStalks } = sunflowerCounts(built);
    checks.push(ok('Sunflowers grow two blocks tall, a stalk under each flower', heads > 0 && onStalks === heads, `${onStalks} of ${heads} sunflowers on stalks`));
  }

  if (world.dimension === 'overworld' && def?.dimension !== 'end' && biome !== 'all') {
    const here = world.getBiome(centre.x, centre.z);
    checks.push(ok(`The spawn is in ${def?.name ?? biome}`, here === biome, `the biome at the spawn is ${getBiomeDef(here)?.name ?? here}`));
  }
  return checks;
}

/** The facts the page lists beside the checklist. */
export function biomeSummary(built) {
  const { world, spawn, def, centre } = built;
  const surface = new Map();
  for (let x = -16; x <= 16; x += 2) for (let z = -16; z <= 16; z += 2) {
    const y = world.getHighestSolidY?.(centre.x + x, centre.z + z) ?? 0;
    const id = world.getVoxel(centre.x + x, y, centre.z + z);
    if (id) surface.set(id, (surface.get(id) ?? 0) + 1);
  }
  return {
    name: def?.name ?? built.biome,
    dimension: world.dimension,
    spawn: `${centre.x}, ${centre.y}, ${centre.z}`,
    reason: spawn?.reason ?? '',
    spawnKind: world.dimension === 'the_end' ? END_SPAWNS[built.biome] ?? 'main' : null,
    surface: [...surface.entries()].sort((a, b) => b[1] - a[1]).slice(0, 5).map(([id, n]) => `${BLOCK_DEFS[id]?.name ?? id} (${n})`),
    mobs: def?.mobs ?? [],
    portal: world.spawnPortals ? `to ${getBiomeDef(world.spawnPortals.overworld.biome)?.name} at ${Math.floor(world.spawnPortals.overworld.x)}, ${Math.floor(world.spawnPortals.overworld.z)}` : null
  };
}

/**
 * "Defeat the dragon" in an End world: the small gateways to the nearest End city and back open, as they do when the
 * dragon dies in the game (bossFights.js onDragonDefeated). Returns where they are, or null outside the End.
 */
export function simulateDragonDefeat(built) {
  if (built.world.dimension !== 'the_end') return null;
  const links = openEndCityLinks(built.world);
  const gateways = endStateFor(built.world).gateways.filter((g) => g.link);
  return { links, gateways: gateways.map((g) => ({ link: g.link, x: g.x, y: g.y, z: g.z, to: g.destination })) };
}
